questions.explanation:
十进制转十六进制采用除 16 取余、逆序排列法：余数 0-9 直接转字符，余数 10-15 转字母 A-F；注意 n = 0 时特判输出 0。参考程序：

```cpp
#include <iostream>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;
    if (n == 0) {
        cout << "0" << endl;
        return 0;
    }
    string ans = "";
    while (n > 0) {
        int r = n % 16;
        if (r < 10) ans = char('0' + r) + ans;
        else ans = char('A' + r - 10) + ans;
        n /= 16;
    }
    cout << ans << endl;
    return 0;
}
```

用字符串读入两个大整数，逆序存入数组（低位在前），逐位相乘累加到结果数组，再统一处理进位，最后逆序输出并去掉前导0。参考程序：

```cpp
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string a, b;
    cin >> a >> b;
    vector<int> A, B, res(a.size() + b.size() + 1, 0);
    // 低位在前
    for (int i = a.size() - 1; i >= 0; i--) A.push_back(a[i] - '0');
    for (int i = b.size() - 1; i >= 0; i--) B.push_back(b[i] - '0');
    // 逐位相乘
    for (int i = 0; i < A.size(); i++) {
        for (int j = 0; j < B.size(); j++) {
            res[i + j] += A[i] * B[j];
        }
    }
    // 处理进位
    for (int i = 0; i < res.size(); i++) {
        if (res[i] >= 10) {
            res[i + 1] += res[i] / 10;
            res[i] %= 10;
        }
    }
    // 去掉前导0
    int k = res.size() - 1;
    while (k > 0 && res[k] == 0) k--;
    for (int i = k; i >= 0; i--) cout << res[i];
    cout << endl;
    return 0;
}
```

